import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherReports({ subject }) {
  const [resultsList, setResultsList] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');

  // Fetch student live metrics from the 3NF Backend Repository
  const fetchLiveResults = () => {
    axios.get('http://localhost:8082/api/student-results')
      .then(res => {
        setResultsList(Array.isArray(res.data) ? res.data : []);
      })
      .catch(err => console.error("Error connecting to results engine:", err));
  };

  useEffect(() => {
    fetchLiveResults();
  }, []);

  // --- DYNAMIC STATISTICAL CALCULATORS ---
  const totalRecords = resultsList.length;
  
  const classAverage = totalRecords > 0 
    ? Math.round(resultsList.reduce((sum, r) => sum + (parseInt(m.marks_obtained || r.score || r.marks_obtained, 10) || 0), 0) / totalRecords)
    : 0;

  const highestMark = totalRecords > 0
    ? Math.max(...resultsList.map(r => parseInt(r.marks_obtained || r.score || 0, 10)))
    : 0;

  const totalPassed = resultsList.filter(r => {
    const mark = parseInt(r.marks_obtained || r.score || 0, 10);
    return mark >= 40;
  }).length;

  const overallPassRate = totalRecords > 0 ? Math.round((totalPassed / totalRecords) * 100) : 0;

  // Filter Pipeline Logic
  const filteredData = resultsList.filter(r => {
    const nameMatch = String(r.student_name).toLowerCase().includes(searchQuery.toLowerCase());
    const currentMark = parseInt(r.marks_obtained || r.score || 0, 10);
    const calculatedStatus = currentMark >= 40 ? 'Pass' : 'Fail';
    const statusMatch = statusFilter === 'All' ? true : calculatedStatus === statusFilter;
    return nameMatch && statusMatch;
  });

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '25px', fontFamily: 'sans-serif' }}>
      
      {/* TOP SUMMARY PANELS */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h2 style={{ margin: 0, fontSize: '22px', fontWeight: 'bold', color: '#1e293b' }}>Student Academic Performance Matrix</h2>
          <p style={{ margin: '4px 0 0 0', fontSize: '13px', color: '#64748b' }}>Live stream statistical analysis driven by relational evaluation metrics.</p>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px' }}>
        <div style={styles.statCard('#3b82f6')}>
          <div>
            <p style={styles.statLabel}>CLASS AVERAGE SCORE</p>
            <h2 style={styles.statCount}>{classAverage}%</h2>
          </div>
          <span style={{ fontSize: '28px' }}>🎯</span>
        </div>
        <div style={styles.statCard('#145c2e')}>
          <div>
            <p style={styles.statLabel}>HIGHEST MARKS RECORDED</p>
            <h2 style={styles.statCount}>{highestMark}%</h2>
          </div>
          <span style={{ fontSize: '28px' }}>🏆</span>
        </div>
        <div style={styles.statCard('#eab308')}>
          <div>
            <p style={styles.statLabel}>OVERALL PASS RATE</p>
            <h2 style={styles.statCount}>{overallPassRate}%</h2>
          </div>
          <span style={{ fontSize: '28px' }}>📈</span>
        </div>
      </div>

      {/* 🟢 PREMIUM VISUAL DATA GRAPH MODULE (WITH Y-AXIS GRID LINES) */}
      <div style={styles.graphContainerBlock}>
        <h3 style={styles.graphBlockTitle}>📊 Live Academic Batch Grade Distribution Chart</h3>
        <p style={{ margin: '-8px 0 20px 0', fontSize: '12.5px', color: '#64748b' }}>Comparative analytics mapping student benchmarks natively against a 0% - 100% evaluation grid.</p>
        
        <div style={styles.chartWorkspace}>
          {/* Background Y-Axis Axis Increments */}
          <div style={styles.axisGridWrapper}>
            <div style={styles.gridLineRow}><span style={styles.axisLabel}>100%</span><div style={styles.lineBar}></div></div>
            <div style={styles.gridLineRow}><span style={styles.axisLabel}>75%</span><div style={styles.lineBar}></div></div>
            <div style={styles.gridLineRow}><span style={styles.axisLabel}>50%</span><div style={styles.lineBar}></div></div>
            <div style={styles.gridLineRow}><span style={styles.axisLabel}>25%</span><div style={styles.lineBar}></div></div>
            <div style={styles.gridLineRow}><span style={styles.axisLabel}>0%</span><div style={{ ...styles.lineBar, borderTop: '2px solid #94a3b8' }}></div></div>
          </div>

          {/* Dynamic Vertical Column Bars */}
          <div style={styles.columnsContainer}>
            {resultsList.map((student, idx) => {
              const currentScore = parseInt(student.marks_obtained || student.score || 0, 10);
              const isPass = currentScore >= 40;
              return (
                <div key={idx} style={styles.chartColumnColumn}>
                  <div style={styles.barTrackSpace}>
                    {/* The Fill Bar Block */}
                    <div style={{
                      ...styles.activeFillBar(isPass ? '#145c2e' : '#dc2626'),
                      height: `${Math.min(currentScore, 100)}%`
                    }}>
                      <span style={styles.barValueTooltip}>{currentScore}%</span>
                    </div>
                  </div>
                  <span style={styles.studentLabelName}>{student.student_name}</span>
                </div>
              );
            })}
            {resultsList.length === 0 && (
              <p style={{ gridColumn: '1/-1', textAlign: 'center', color: '#94a3b8', fontStyle: 'italic', padding: '40px 0' }}>No database analytics entries available to chart map.</p>
            )}
          </div>
        </div>
      </div>

      {/* FILTER GATEWAY TOOLBAR */}
      <div style={styles.toolbarDock}>
        <input 
          type="text" 
          placeholder="Search student records dynamically..." 
          value={searchQuery}
          onChange={e => setSearchQuery(e.target.value)}
          style={styles.searchBarBox}
        />
        <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} style={styles.toolbarSelector}>
          <option value="All">All Evaluation Statuses</option>
          <option value="Pass">Pass Stream Only</option>
          <option value="Fail">Fail Stream Only</option>
        </select>
      </div>

      {/* DATA ARCHIVE MATRIX TABLE */}
      <div style={styles.tableWrapperCard}>
        <table style={styles.matrixTableElement}>
          <thead>
            <tr style={styles.tableHeaderRow}>
              <th style={{ width: '60px', paddingLeft: '20px' }}>No.</th>
              <th>Student Name</th>
              <th>Grade Instance</th>
              <th>Assigned Subject</th>
              <th>Quiz / Exam Evaluation Module</th>
              <th>Marks Secured</th>
              <th style={{ width: '100px', textAlign: 'center' }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {filteredData.map((row, index) => {
              const currentMark = parseInt(row.marks_obtained || row.score || 0, 10);
              const totalPaperMark = parseInt(row.total_marks, 10) || 100;
              const isPass = currentMark >= 40;

              return (
                <tr key={row.id || index} style={styles.tableBodyRow}>
                  <td style={{ fontWeight: 'bold', color: '#94a3b8', paddingLeft: '20px' }}>{index + 1}</td>
                  <td style={{ fontWeight: '600', color: '#1e293b' }}>{row.student_name}</td>
                  <td><span style={styles.inlineBadge}>{row.grade || 'Grade 8'}</span></td>
                  <td style={{ color: '#64748b', fontWeight: '500' }}>{row.subject_name || 'Mathematics'}</td>
                  <td style={{ fontStyle: 'italic', color: '#334155' }}>{row.quiz_title}</td>
                  <td style={{ fontWeight: 'bold', color: isPass ? '#145c2e' : '#dc2626' }}>{currentMark} / {totalPaperMark}</td>
                  <td style={{ textAlign: 'center' }}>
                    <span style={styles.statusPillBadge(isPass)}>{isPass ? 'Pass' : 'Fail'}</span>
                  </td>
                </tr>
              );
            })}
            {filteredData.length === 0 && (
              <tr><td colSpan="7" style={styles.tableEmptyMessage}>No student validation entries matched the current query bounds.</td></tr>
            )}
          </tbody>
        </table>
      </div>

    </div>
  );
}

const styles = {
  statCard: (color) => ({ backgroundColor: 'white', padding: '22px 25px', borderRadius: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `6px solid ${color}`, boxShadow: '0 4px 15px rgba(0,0,0,0.015)', borderTop: '1px solid #f1f5f9', borderRight: '1px solid #f1f5f9', borderBottom: '1px solid #f1f5f9' }),
  statLabel: { margin: 0, color: '#64748b', fontSize: '11px', fontWeight: 'bold', letterSpacing: '0.5px' },
  statCount: { fontSize: '20px', fontWeight: 'bold', color: '#1e293b', margin: '4px 0 0 0' },
  graphContainerBlock: { backgroundColor: 'white', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 20px rgba(0,0,0,0.01)' },
  graphBlockTitle: { margin: '0 0 12px 0', fontSize: '15.5px', fontWeight: 'bold', color: '#1e293b' },
  chartWorkspace: { position: 'relative', height: '260px', marginTop: '10px', display: 'flex', alignItems: 'stretch' },
  axisGridWrapper: { position: 'absolute', top: 0, left: 0, right: 0, height: '210px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', pointerEvents: 'none' },
  gridLineRow: { display: 'flex', alignItems: 'center', width: '100%', height: '0px' },
  axisLabel: { width: '45px', fontSize: '11px', fontWeight: 'bold', color: '#94a3b8', textAlign: 'right', paddingRight: '10px' },
  lineBar: { flex: 1, borderTop: '1px dashed #e2e8f0' },
  columnsContainer: { flex: 1, paddingLeft: '45px', display: 'flex', justifyContent: 'space-around', alignItems: 'stretch', height: '210px', zIndex: 2 },
  chartColumnColumn: { width: '65px', display: 'flex', flexDirection: 'column', justifyContent: 'end', alignItems: 'center', height: '100%' },
  barTrackSpace: { width: '28px', height: '100%', display: 'flex', flexDirection: 'column', justifyContent: 'end', backgroundColor: '#f1f5f9', borderRadius: '6px 6px 0 0', overflow: 'visible' },
  activeFillBar: (color) => ({ width: '100%', backgroundColor: color, borderRadius: '5px 5px 0 0', position: 'relative', display: 'flex', justifyContent: 'center', transition: 'height 0.6s cubic-bezier(0.4, 0, 0.2, 1)' }),
  barValueTooltip: { position: 'absolute', top: '-24px', backgroundColor: '#1e293b', color: 'white', fontSize: '10px', fontWeight: 'bold', padding: '2px 6px', borderRadius: '4px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)' },
  studentLabelName: { fontSize: '12px', fontWeight: 'bold', color: '#475569', marginTop: '12px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', width: '75px', textAlign: 'center', position: 'absolute', bottom: '-35px' },
  toolbarDock: { display: 'flex', gap: '15px', marginTop: '15px' },
  searchBarBox: { flex: 1, padding: '11px 16px', borderRadius: '10px', border: '1px solid #cbd5e1', backgroundColor: 'white', fontSize: '13.5px', outline: 'none' },
  toolbarSelector: { padding: '0 15px', borderRadius: '10px', border: '1px solid #145c2e', backgroundColor: 'white', fontSize: '13px', fontWeight: 'bold', color: '#145c2e', outline: 'none', cursor: 'pointer' },
  tableWrapperCard: { backgroundColor: 'white', borderRadius: '16px', border: '1px solid #e2e8f0', overflowX: 'auto', boxShadow: '0 4px 20px rgba(0,0,0,0.01)' },
  matrixTableElement: { width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '850px' },
  tableHeaderRow: { borderBottom: '1px solid #f1f5f9', color: '#64748b', fontSize: '12px', height: '45px', textTransform: 'uppercase', letterSpacing: '0.5px' },
  tableBodyRow: { borderBottom: '1px solid #f8fafc', height: '65px', transition: 'background-color 0.2s' },
  inlineBadge: { backgroundColor: '#f1f5f9', color: '#475569', padding: '4px 10px', borderRadius: '6px', fontSize: '11.5px', fontWeight: 'bold' },
  statusPillBadge: (pass) => ({ padding: '5px 12px', borderRadius: '8px', fontSize: '11.5px', fontWeight: 'bold', backgroundColor: pass ? '#dcfce7' : '#fee2e2', color: pass ? '#15803d' : '#b91c1c' }),
  tableEmptyMessage: { textAlign: 'center', padding: '40px', color: '#94a3b8', fontStyle: 'italic', fontSize: '13.5px' }
};
